package reasoning

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// Reasoning is the canonical scalar for model-side reasoning controls.
type Reasoning string

const (
	ReasoningAuto    Reasoning = "auto"
	ReasoningOff     Reasoning = "off"
	ReasoningLow     Reasoning = "low"
	ReasoningMedium  Reasoning = "medium"
	ReasoningHigh    Reasoning = "high"
	ReasoningMinimal Reasoning = "minimal"
	ReasoningXHigh   Reasoning = "xhigh"
	ReasoningMax     Reasoning = "max"
)

// PortableBudgets are fallback named reasoning token budgets.
var PortableBudgets = map[Reasoning]int{
	ReasoningOff:    0,
	ReasoningLow:    2048,
	ReasoningMedium: 8192,
	ReasoningHigh:   32768,
}

// ReasoningTokens returns a numeric reasoning-token request.
func ReasoningTokens(n int) Reasoning {
	return Reasoning(strconv.Itoa(n))
}

type Kind string

const (
	KindUnset  Kind = "unset"
	KindAuto   Kind = "auto"
	KindOff    Kind = "off"
	KindNamed  Kind = "named"
	KindTokens Kind = "tokens"
)

type Policy struct {
	Kind   Kind
	Value  Reasoning
	Tokens int
}

func (p Policy) IsSet() bool {
	return p.Kind != KindUnset
}

func (p Policy) IsExplicitOff() bool {
	return p.Kind == KindOff || (p.Kind == KindTokens && p.Tokens == 0)
}

func Normalize(value string) (Reasoning, error) {
	p, err := ParseString(value)
	if err != nil {
		return "", err
	}
	return p.Value, nil
}

func ParseString(value string) (Policy, error) {
	s := strings.ToLower(strings.TrimSpace(value))
	if s == "" {
		return Policy{Kind: KindUnset}, nil
	}
	switch s {
	case "auto":
		return Policy{Kind: KindAuto, Value: ReasoningAuto}, nil
	case "off", "none", "false":
		return Policy{Kind: KindOff, Value: ReasoningOff}, nil
	case "low":
		return Policy{Kind: KindNamed, Value: ReasoningLow}, nil
	case "medium":
		return Policy{Kind: KindNamed, Value: ReasoningMedium}, nil
	case "high":
		return Policy{Kind: KindNamed, Value: ReasoningHigh}, nil
	case "minimal":
		return Policy{Kind: KindNamed, Value: ReasoningMinimal}, nil
	case "x-high", "x_high", "xhigh":
		return Policy{Kind: KindNamed, Value: ReasoningXHigh}, nil
	case "max":
		return Policy{Kind: KindNamed, Value: ReasoningMax}, nil
	}
	tokens, err := strconv.Atoi(s)
	if err == nil {
		if tokens < 0 {
			return Policy{}, fmt.Errorf("reasoning: negative token budget %d is invalid", tokens)
		}
		if tokens == 0 {
			return Policy{Kind: KindOff, Value: ReasoningOff, Tokens: 0}, nil
		}
		return Policy{Kind: KindTokens, Value: ReasoningTokens(tokens), Tokens: tokens}, nil
	}
	return Policy{}, fmt.Errorf("reasoning: unsupported value %q", value)
}

func Parse(value any) (Policy, error) {
	switch v := value.(type) {
	case nil:
		return Policy{Kind: KindUnset}, nil
	case Reasoning:
		return ParseString(string(v))
	case string:
		return ParseString(v)
	case int:
		return ParseString(strconv.Itoa(v))
	case int64:
		return ParseString(strconv.FormatInt(v, 10))
	case float64:
		if v != float64(int(v)) {
			return Policy{}, fmt.Errorf("reasoning: numeric value %v must be an integer", v)
		}
		return ParseString(strconv.Itoa(int(v)))
	case json.Number:
		i, err := strconv.Atoi(v.String())
		if err != nil {
			return Policy{}, fmt.Errorf("reasoning: numeric value %q must be an integer", v.String())
		}
		return ParseString(strconv.Itoa(i))
	default:
		return Policy{}, fmt.Errorf("reasoning: unsupported scalar type %T", value)
	}
}

// BudgetForNamed returns the PortableBudgets token budget for a named reasoning
// tier. Returns 0 for tiers without a portable budget (off, minimal, xhigh, max).
func BudgetForNamed(r Reasoning) int {
	return PortableBudgets[r]
}

// NearestTierForTokens snaps a token count to the nearest PortableBudgets tier
// using log2-scale distance; ties round up to the higher tier.
// Boundaries (geometric midpoints): <4096 → low, [4096,16384) → medium, ≥16384 → high.
func NearestTierForTokens(n int) Reasoning {
	if n < 4096 {
		return ReasoningLow
	}
	if n < 16384 {
		return ReasoningMedium
	}
	return ReasoningHigh
}

func BudgetFor(policy Policy, budgets map[Reasoning]int, maxTokens int) (int, error) {
	switch policy.Kind {
	case KindUnset, KindAuto:
		return 0, nil
	case KindOff:
		return 0, nil
	case KindTokens:
		if maxTokens > 0 && policy.Tokens > maxTokens {
			return 0, fmt.Errorf("reasoning: token budget %d exceeds maximum %d", policy.Tokens, maxTokens)
		}
		return policy.Tokens, nil
	case KindNamed:
		if policy.Value == ReasoningMax {
			if maxTokens <= 0 {
				return 0, fmt.Errorf("reasoning: max requires a known model/provider maximum")
			}
			return maxTokens, nil
		}
		if budgets != nil {
			if budget, ok := budgets[policy.Value]; ok {
				return budget, nil
			}
		}
		if budget, ok := PortableBudgets[policy.Value]; ok {
			if maxTokens > 0 && budget > maxTokens {
				return 0, fmt.Errorf("reasoning: %s budget %d exceeds maximum %d", policy.Value, budget, maxTokens)
			}
			return budget, nil
		}
		return 0, fmt.Errorf("reasoning: unsupported named value %q for numeric budget", policy.Value)
	default:
		return 0, fmt.Errorf("reasoning: unsupported policy kind %q", policy.Kind)
	}
}

func (r *Reasoning) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err == nil {
		normalized, err := Normalize(s)
		if err != nil {
			return err
		}
		*r = normalized
		return nil
	}
	var n json.Number
	if err := json.Unmarshal(data, &n); err == nil {
		policy, err := Parse(n)
		if err != nil {
			return err
		}
		*r = policy.Value
		return nil
	}
	return fmt.Errorf("reasoning: JSON value must be a string or integer")
}

func (r *Reasoning) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		policy, err := ParseString(value.Value)
		if err != nil {
			return err
		}
		*r = policy.Value
		return nil
	default:
		return fmt.Errorf("reasoning: YAML value must be a scalar")
	}
}

package harnesses

import "github.com/easel/fizeau/internal/reasoning"

// AdapterReasoningValue resolves the public reasoning scalar into the value
// subprocess harnesses should pass to their native CLI flag. Empty, auto, off,
// and numeric 0 intentionally emit no flag.
func AdapterReasoningValue(req ExecuteRequest) string {
	value := req.Reasoning
	policy, err := reasoning.ParseString(value)
	if err != nil {
		return value
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return ""
	case reasoning.KindTokens:
		if policy.Tokens == 0 {
			return ""
		}
		return string(policy.Value)
	case reasoning.KindNamed:
		return string(policy.Value)
	default:
		return value
	}
}

package harnesses

import (
	"context"
	"encoding/json"
	"time"
)

// AccountInfo captures provider account metadata from local auth files.
type AccountInfo struct {
	Email    string `json:"email,omitempty"`
	PlanType string `json:"plan_type,omitempty"`
	OrgName  string `json:"org_name,omitempty"`
}

// QuotaWindow captures one quota window (e.g. 5h, weekly, model-specific).
type QuotaWindow struct {
	Name          string  `json:"name"`               // e.g. "5h", "7d", "spark"
	LimitID       string  `json:"limit_id,omitempty"` // provider limit_id
	LimitName     string  `json:"limit_name,omitempty"`
	WindowMinutes int     `json:"window_minutes"`
	UsedPercent   float64 `json:"used_percent"`
	ResetsAt      string  `json:"resets_at,omitempty"`      // human-readable
	ResetsAtUnix  int64   `json:"resets_at_unix,omitempty"` // unix timestamp
	State         string  `json:"state"`
}

// QuotaStateFromUsedPercent maps a usage percentage to a quota state string.
func QuotaStateFromUsedPercent(usedPercent int) string {
	if usedPercent >= 95 {
		return "blocked"
	}
	if usedPercent >= 0 {
		return "ok"
	}
	return "unknown"
}

// ModelDiscoverySnapshot captures model and reasoning capability evidence for
// harnesses whose source of truth is a CLI/TUI surface instead of /v1/models.
type ModelDiscoverySnapshot struct {
	CapturedAt      time.Time `json:"captured_at"`
	Models          []string  `json:"models,omitempty"`
	ReasoningLevels []string  `json:"reasoning_levels,omitempty"`
	Source          string    `json:"source"`
	FreshnessWindow string    `json:"freshness_window,omitempty"`
	Detail          string    `json:"detail,omitempty"`
}

// EventType identifies the kind of event a harness emits during execution.
//
// The set is the closed union defined by CONTRACT-003 ("Event JSON shapes"):
// every backend (native + subprocess) emits these identically so the agent
// loop can multiplex them onto a single channel.
type EventType string

const (
	EventTypeTextDelta       EventType = "text_delta"
	EventTypeToolCall        EventType = "tool_call"
	EventTypeToolResult      EventType = "tool_result"
	EventTypeCompaction      EventType = "compaction"
	EventTypeProgress        EventType = "progress"
	EventTypeRoutingDecision EventType = "routing_decision"
	EventTypeStall           EventType = "stall"
	EventTypeFinal           EventType = "final"
)

// Event is the structured event a harness emits during Execute. It mirrors
// the shape defined in CONTRACT-003 §"Event JSON shapes". The Data field is
// a JSON-encoded payload whose schema is determined by Type.
type Event struct {
	Type     EventType         `json:"type"`
	Sequence int64             `json:"sequence"`
	Time     time.Time         `json:"time"`
	Metadata map[string]string `json:"metadata,omitempty"`
	Data     json.RawMessage   `json:"data"`
}

// TextDeltaData is the payload for type=text_delta events.
type TextDeltaData struct {
	Text string `json:"text"`
}

// ToolCallData is the payload for type=tool_call events.
type ToolCallData struct {
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input,omitempty"`
}

// ToolResultData is the payload for type=tool_result events.
type ToolResultData struct {
	ID         string `json:"id"`
	Output     string `json:"output,omitempty"`
	Error      string `json:"error,omitempty"`
	DurationMS int64  `json:"duration_ms,omitempty"`
}

// FinalData is the payload for type=final events.
type FinalData struct {
	Status         string            `json:"status"` // success|iteration_limit|failed|stalled|timed_out|cancelled
	ExitCode       int               `json:"exit_code"`
	Error          string            `json:"error,omitempty"`
	FinalText      string            `json:"final_text,omitempty"`
	DurationMS     int64             `json:"duration_ms"`
	Usage          *FinalUsage       `json:"usage,omitempty"`
	Warnings       []FinalWarning    `json:"warnings,omitempty"`
	CostUSD        float64           `json:"cost_usd,omitempty"`
	SessionLogPath string            `json:"session_log_path,omitempty"`
	RoutingActual  *RoutingActual    `json:"routing_actual,omitempty"`
	Extra          map[string]string `json:"-"`
}

// FinalUsage carries token totals on a final event. Count fields are pointers
// so unavailable token dimensions are omitted instead of serialized as zero.
// A present pointer to 0 means the harness explicitly reported zero usage.
type FinalUsage struct {
	InputTokens      *int                  `json:"input_tokens,omitempty"`
	OutputTokens     *int                  `json:"output_tokens,omitempty"`
	CacheReadTokens  *int                  `json:"cache_read_tokens,omitempty"`
	CacheWriteTokens *int                  `json:"cache_write_tokens,omitempty"`
	CacheTokens      *int                  `json:"cache_tokens,omitempty"`
	ReasoningTokens  *int                  `json:"reasoning_tokens,omitempty"`
	TotalTokens      *int                  `json:"total_tokens,omitempty"`
	Source           string                `json:"source,omitempty"`
	Fresh            *bool                 `json:"fresh,omitempty"`
	CapturedAt       string                `json:"captured_at,omitempty"`
	Sources          []UsageSourceEvidence `json:"sources,omitempty"`
}

// FinalWarning is normalized metadata about non-fatal final-event issues.
type FinalWarning struct {
	Code    string                `json:"code"`
	Message string                `json:"message,omitempty"`
	Sources []UsageSourceEvidence `json:"sources,omitempty"`
}

// UsageSourceEvidence records one usage source considered by the resolver.
type UsageSourceEvidence struct {
	Source     string            `json:"source"`
	Fresh      *bool             `json:"fresh,omitempty"`
	CapturedAt string            `json:"captured_at,omitempty"`
	Usage      *UsageTokenCounts `json:"usage,omitempty"`
	Warning    string            `json:"warning,omitempty"`
}

// UsageTokenCounts is the normalized token-count vocabulary shared by
// subprocess harnesses and CONTRACT-003 final metadata.
type UsageTokenCounts struct {
	InputTokens      *int `json:"input_tokens,omitempty"`
	OutputTokens     *int `json:"output_tokens,omitempty"`
	CacheReadTokens  *int `json:"cache_read_tokens,omitempty"`
	CacheWriteTokens *int `json:"cache_write_tokens,omitempty"`
	CacheTokens      *int `json:"cache_tokens,omitempty"`
	ReasoningTokens  *int `json:"reasoning_tokens,omitempty"`
	TotalTokens      *int `json:"total_tokens,omitempty"`
}

// Any reports whether at least one token dimension is known.
func (c UsageTokenCounts) Any() bool {
	return c.InputTokens != nil ||
		c.OutputTokens != nil ||
		c.CacheReadTokens != nil ||
		c.CacheWriteTokens != nil ||
		c.CacheTokens != nil ||
		c.ReasoningTokens != nil ||
		c.TotalTokens != nil
}

func IntPtr(v int) *int {
	return &v
}

func BoolPtr(v bool) *bool {
	return &v
}

// RoutingActual captures the resolved fallback chain on a final event.
type RoutingActual struct {
	Harness            string   `json:"harness"`
	Provider           string   `json:"provider,omitempty"`
	ServerInstance     string   `json:"server_instance,omitempty"`
	Model              string   `json:"model"`
	FallbackChainFired []string `json:"fallback_chain_fired,omitempty"`
	FailureClass       string   `json:"failure_class,omitempty"`
	// Power is the catalog-projected power of the actually-dispatched
	// Model. 0 means unknown/exact-pin-only/no catalog entry.
	Power int `json:"power,omitempty"`
}

// HarnessInfo describes a registered harness. Mirrors the public
// HarnessInfo type defined in CONTRACT-003. Internal callers use this to
// implement the public ListHarnesses surface without re-declaring the shape.
type HarnessInfo struct {
	Name                 string
	Type                 string // "native" | "subprocess"
	Available            bool
	Path                 string
	Error                string
	IsLocal              bool
	IsSubscription       bool
	AutoRoutingEligible  bool
	ExactPinSupport      bool
	DefaultModel         string
	SupportedPermissions []string
	SupportedReasoning   []string
	CostClass            string
}

// ExecuteRequest is the internal request carried into Harness.Execute. It
// is intentionally narrower than the public ExecuteRequest in CONTRACT-003:
// the agent's routing layer is expected to resolve provider/model/reasoning
// /permissions/timeouts before invoking a harness, so the harness sees a
// concrete, ready-to-run request.
type ExecuteRequest struct {
	// Prompt is the resolved user prompt sent to the model.
	Prompt string

	// SystemPrompt is the resolved system prompt; empty means harness default.
	SystemPrompt string

	// Provider is the resolved provider identifier when applicable. May be
	// empty for harnesses that have no provider concept (e.g. claude CLI).
	Provider string

	// Model is the resolved model identifier; empty means harness default.
	Model string

	// WorkDir is the working directory for tool operations. Required when
	// the chosen harness uses tools.
	WorkDir string

	// Permissions is "safe" | "supervised" | "unrestricted". Empty defaults to "safe".
	Permissions string

	// Temperature is the model sampling temperature requested by the caller.
	// Harness adapters may ignore it when their CLI has no equivalent control.
	Temperature float32

	// Seed is the requested sampling seed. Zero means unset/provider chooses.
	// Harness adapters may ignore it when their CLI has no equivalent control.
	Seed int64

	// Reasoning is the normalized public reasoning scalar. Empty/off means no
	// adapter flag should be emitted.
	Reasoning string

	// Timeout is the wall-clock cap for the entire request. 0 disables.
	Timeout time.Duration

	// IdleTimeout is the streaming-quiet cap. 0 uses harness default.
	IdleTimeout time.Duration

	// SessionLogDir overrides the per-run session-log directory; harness
	// uses this to direct progress traces into a per-bundle evidence dir.
	SessionLogDir string

	// SessionID is a stable identifier for the run, used in progress log
	// filenames and event metadata. Empty means the harness generates one.
	SessionID string

	// Metadata is echoed back into Event.Metadata (e.g. bead_id, attempt_id).
	Metadata map[string]string
}

// Harness is the internal contract every harness implementation in
// internal/harnesses/<name> satisfies. It is the minimal surface the agent
// dispatcher needs to route a resolved request into a backend.
//
// A Harness is responsible for emitting events on the returned channel until
// execution completes; the channel MUST be closed after the final event so
// downstream consumers can detect end-of-stream. The final event is always
// of type EventTypeFinal.
type Harness interface {
	// Info returns identity + capability metadata for this harness.
	Info() HarnessInfo

	// HealthCheck triggers a fresh probe (binary present, auth ok, etc.)
	// and returns nil if the harness is ready to execute.
	HealthCheck(ctx context.Context) error

	// Execute runs one resolved request. Events stream on the returned
	// channel; a single final event closes the stream. The first error
	// return is reserved for setup failures (binary missing, etc.) — once
	// the channel is returned, all per-run failures are reported via a
	// final event with Status != "success".
	Execute(ctx context.Context, req ExecuteRequest) (<-chan Event, error)
}

package codex

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	osexec "os/exec"
	"strings"
	"syscall"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelcatalog"
)

const defaultEventBuffer = 64

// Fallback only: unpinned runs resolve through model discovery first.
const fallbackDefaultModel = "gpt-5.4"

// Runner is the subprocess-backed codex harness. It launches codex in
// exec --json mode, parses each JSONL line into harness Events, and emits
// a final Event when the subprocess exits.
type Runner struct {
	// Binary is the absolute path to the codex executable. When empty the
	// runner resolves "codex" via PATH at Execute time.
	Binary string

	// BaseArgs is prepended to the per-request argument list.
	// Codex default: ["exec", "--json"]
	BaseArgs []string

	// PromptMode controls how the prompt is delivered:
	//   "arg" (default) — prompt is appended as the final positional argument
	//   "stdin"         — prompt is piped on stdin
	PromptMode string

	// EventBuffer overrides the per-Execute channel buffer size.
	EventBuffer int
}

// Info returns identity + capability metadata for this harness.
func (r *Runner) Info() harnesses.HarnessInfo {
	info := harnesses.HarnessInfo{
		Name:                 "codex",
		Type:                 "subprocess",
		IsLocal:              false,
		IsSubscription:       true,
		AutoRoutingEligible:  true,
		ExactPinSupport:      true,
		DefaultModel:         harnesses.ResolveRunnerModel("codex", modelcatalog.SurfaceCodex, "", fallbackDefaultModel).ResolvedModel,
		SupportedPermissions: []string{"safe", "supervised", "unrestricted"},
		SupportedReasoning:   []string{"low", "medium", "high", "xhigh", "max"},
		CostClass:            "medium",
	}
	path := r.Binary
	if path == "" {
		if resolved, err := osexec.LookPath("codex"); err == nil {
			path = resolved
		}
	}
	if path != "" {
		info.Path = path
		info.Available = true
	} else {
		info.Error = "codex binary not found in PATH"
	}
	return info
}

// HealthCheck verifies the codex binary is present.
func (r *Runner) HealthCheck(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	path := r.Binary
	if path == "" {
		resolved, err := osexec.LookPath("codex")
		if err != nil {
			return fmt.Errorf("codex binary not found: %w", err)
		}
		path = resolved
	}
	st, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("stat codex binary: %w", err)
	}
	if st.IsDir() {
		return fmt.Errorf("codex binary path is a directory: %s", path)
	}
	return nil
}

// Execute runs one resolved request through the codex CLI and emits
// JSONL-derived events on the returned channel.
func (r *Runner) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
	binary := r.Binary
	if binary == "" {
		resolved, err := osexec.LookPath("codex")
		if err != nil {
			return nil, fmt.Errorf("codex binary not found: %w", err)
		}
		binary = resolved
	}

	bufSize := r.EventBuffer
	if bufSize <= 0 {
		bufSize = defaultEventBuffer
	}

	out := make(chan harnesses.Event, bufSize)
	go r.run(ctx, binary, req, out)
	return out, nil
}

func (r *Runner) run(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event) {
	defer close(out)

	start := time.Now()
	var seq int64

	agg, exitCode, stderr, runErr, status := r.runStreaming(ctx, binary, req, out, &seq)

	final := harnesses.FinalData{
		Status:     status,
		ExitCode:   exitCode,
		DurationMS: time.Since(start).Milliseconds(),
	}
	if runErr != nil && status != "success" {
		final.Error = runErr.Error()
	} else if stderr != "" && status != "success" {
		final.Error = trimErrorBlob(stderr)
	}
	if agg != nil {
		final.FinalText = agg.FinalText
		final.Usage, final.Warnings = harnesses.ResolveFinalUsage(agg.UsageSources)
		agg.writeTokenCountQuotaCache()
	}

	finalRaw, err := json.Marshal(final)
	if err != nil {
		finalRaw = []byte(`{"status":"failed","error":"marshal final event"}`)
	}
	ev := harnesses.Event{
		Type:     harnesses.EventTypeFinal,
		Sequence: seq,
		Time:     time.Now().UTC(),
		Metadata: req.Metadata,
		Data:     finalRaw,
	}
	select {
	case out <- ev:
	case <-time.After(time.Second):
	}
}

func (a *streamAggregate) writeTokenCountQuotaCache() {
	if a == nil || len(a.TokenCountRateLimits) == 0 {
		return
	}
	var newest *CodexQuotaSnapshot
	for _, evidence := range a.TokenCountRateLimits {
		fallback := time.Now().UTC()
		snapshot, ok := CodexQuotaSnapshotFromTokenCountRateLimits(evidence.CapturedAt, fallback, evidence.RateLimits)
		if !ok {
			continue
		}
		snapshot.Source = "codex_exec_token_count"
		if newest == nil || snapshot.CapturedAt.After(newest.CapturedAt) {
			newest = snapshot
		}
	}
	if newest == nil {
		return
	}
	path, err := CodexQuotaCachePath()
	if err != nil {
		return
	}
	_ = WriteCodexQuota(path, *newest)
}

func (r *Runner) runStreaming(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event, seq *int64) (agg *streamAggregate, exitCode int, stderr string, runErr error, status string) {
	base := r.BaseArgs
	if base == nil {
		base = []string{"exec", "--json"}
	}
	args := append([]string{}, base...)
	modelResolution := harnesses.ResolveRunnerModel("codex", modelcatalog.SurfaceCodex, req.Model, fallbackDefaultModel)

	// Permission args: unrestricted adds --dangerously-bypass-approvals-and-sandbox
	if req.Permissions == "unrestricted" {
		args = append(args, "--dangerously-bypass-approvals-and-sandbox")
	}

	// WorkDir flag: -C <dir>
	if req.WorkDir != "" {
		args = append(args, "-C", req.WorkDir)
	}

	// Model flag: -m <model>
	if modelResolution.ResolvedModel != "" {
		args = append(args, "-m", modelResolution.ResolvedModel)
	}

	// Reasoning flag: -c reasoning.effort=<reasoning>
	if value := harnesses.AdapterReasoningValue(req); value != "" {
		args = append(args, "-c", fmt.Sprintf("reasoning.effort=%s", value))
	}

	promptMode := r.PromptMode
	if promptMode == "" {
		promptMode = "arg"
	}
	if promptMode == "arg" && req.Prompt != "" {
		args = append(args, req.Prompt)
	}

	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	cmd := harnesses.HarnessCommand(runCtx, binary, args...)
	if req.WorkDir != "" {
		cmd.Dir = req.WorkDir
	}
	if promptMode != "arg" {
		cmd.Stdin = strings.NewReader(req.Prompt)
	}
	setProcessGroup(cmd)

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		return nil, -1, "", err, "failed"
	}
	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		return nil, -1, "", err, "failed"
	}

	if err := cmd.Start(); err != nil {
		return nil, -1, "", err, "failed"
	}

	progressLog, _ := harnesses.OpenProgressLog(req.SessionLogDir, req.SessionID, "codex")
	if progressLog != nil {
		defer progressLog.Close()
	}
	if harnesses.ShouldEmitRunnerDefaultResolution(modelResolution) {
		ev := harnesses.RunnerDefaultResolutionEvent(modelResolution, req.Metadata, seq)
		harnesses.WriteProgressEvent(progressLog, ev)
		select {
		case out <- ev:
		case <-ctx.Done():
			return nil, -1, "", ctx.Err(), "cancelled"
		}
	}

	parserReader, parserWriter := io.Pipe()
	parseDone := make(chan struct{})
	var parseAgg *streamAggregate
	var parseErr error
	go func() {
		defer close(parseDone)
		mirrored, mirrorDone := harnesses.MirrorEvents(out, progressLog, ctx)
		defer func() {
			close(mirrored)
			<-mirrorDone
		}()
		parseAgg, parseErr = parseCodexStream(runCtx, parserReader, mirrored, req.Metadata, seq)
	}()

	stdoutDone := make(chan struct{})
	go func() {
		defer close(stdoutDone)
		_, _ = io.Copy(parserWriter, stdoutPipe)
		_ = parserWriter.Close()
	}()

	var stderrBuf strings.Builder
	stderrDone := make(chan struct{})
	go func() {
		defer close(stderrDone)
		_, _ = io.Copy(&stringBuilderWriter{&stderrBuf}, stderrPipe)
	}()

	var timedOut bool
	if req.Timeout > 0 {
		stop := make(chan struct{})
		go func() {
			select {
			case <-stop:
			case <-time.After(req.Timeout):
				timedOut = true
				cancel()
			}
		}()
		defer close(stop)
	}

	cancelDone := make(chan struct{})
	go func() {
		defer close(cancelDone)
		select {
		case <-ctx.Done():
			killProcessGroup(cmd)
		case <-stdoutDone:
		}
	}()

	<-stdoutDone
	<-stderrDone
	<-parseDone
	runErr = cmd.Wait()
	<-cancelDone
	stderr = stderrBuf.String()

	switch {

	if errors.As(err, &exitErr) {
		stderrBytes = string(exitErr.Stderr)
	}

	if err != nil {
		ec := -1
		if exitErr != nil {
			ec = exitErr.ExitCode()
		}
		return nil, ec, stderrBytes, err, "failed"
	}

	text := strings.TrimSpace(string(stdoutBytes))
	if text != "" {
		raw, _ := json.Marshal(harnesses.TextDeltaData{Text: text})
		ev := harnesses.Event{
			Type:     harnesses.EventTypeTextDelta,
			Sequence: *seq,
			Time:     time.Now().UTC(),
			Metadata: req.Metadata,
			Data:     raw,
		}
		*seq++
		select {
		case out <- ev:
		case <-ctx.Done():
			return nil, 0, stderrBytes, ctx.Err(), "cancelled"
		}
	}
	return &streamAggregate{FinalText: text}, 0, stderrBytes, nil, "success"
}

func (r *Runner) buildArgs(base []string, req harnesses.ExecuteRequest) []string {
	args := append([]string{}, base...)
	modelResolution := harnesses.ResolveRunnerModel("claude", modelcatalog.SurfaceClaudeCode, req.Model, fallbackDefaultModel)
	switch req.Permissions {
	case "supervised":
		args = append(args, "--permission-mode", "default")
	case "unrestricted":
		args = append(args, "--permission-mode", "bypassPermissions", "--dangerously-skip-permissions")
	}
	if modelResolution.ResolvedModel != "" {
		args = append(args, "--model", modelResolution.ResolvedModel)
	}
	if value := harnesses.AdapterReasoningValue(req); value != "" {
		args = append(args, "--effort", value)
	}
	return args
}

// stringBuilderWriter adapts *strings.Builder to io.Writer.
type stringBuilderWriter struct {
	sb *strings.Builder
}

func (w *stringBuilderWriter) Write(p []byte) (int, error) {
	return w.sb.Write(p)
}

// trimErrorBlob caps stderr for inclusion in the final event so a runaway
// error log doesn't bloat the channel payload.
func trimErrorBlob(s string) string {
	const max = 2048
	s = strings.TrimSpace(s)
	if len(s) > max {
		return s[:max] + "...(truncated)"
	}
	return s
}

// setProcessGroup configures cmd to start in its own process group on
// POSIX. Implemented in a build-tagged file for cross-platform support.
func setProcessGroup(cmd *osexec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	setProcessGroupAttr(cmd.SysProcAttr)
}

package reasoning

import "testing"

func TestParseReasoningNormalizesScalarValues(t *testing.T) {
	tests := []struct {
		name  string
		input any
		kind  Kind
		value Reasoning
		tok   int
	}{
		{name: "empty", input: "", kind: KindUnset},
		{name: "auto", input: "auto", kind: KindAuto, value: ReasoningAuto},
		{name: "off", input: "off", kind: KindOff, value: ReasoningOff},
		{name: "none", input: "none", kind: KindOff, value: ReasoningOff},
		{name: "false", input: "false", kind: KindOff, value: ReasoningOff},
		{name: "zero string", input: "0", kind: KindOff, value: ReasoningOff},
		{name: "zero int", input: 0, kind: KindOff, value: ReasoningOff},
		{name: "low", input: "low", kind: KindNamed, value: ReasoningLow},
		{name: "medium", input: "medium", kind: KindNamed, value: ReasoningMedium},
		{name: "high", input: "high", kind: KindNamed, value: ReasoningHigh},
		{name: "minimal", input: "minimal", kind: KindNamed, value: ReasoningMinimal},
		{name: "x-high", input: "x-high", kind: KindNamed, value: ReasoningXHigh},
		{name: "max", input: "max", kind: KindNamed, value: ReasoningMax},
		{name: "tokens string", input: "1234", kind: KindTokens, value: Reasoning("1234"), tok: 1234},
		{name: "tokens int", input: 1234, kind: KindTokens, value: Reasoning("1234"), tok: 1234},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Parse(tt.input)
			if err != nil {
				t.Fatalf("Parse(%v) returned error: %v", tt.input, err)
			}
			if got.Kind != tt.kind || got.Value != tt.value || got.Tokens != tt.tok {
				t.Fatalf("Parse(%v) = %#v, want kind=%s value=%q tokens=%d", tt.input, got, tt.kind, tt.value, tt.tok)
			}
		})
	}
}

func TestBudgetForPortableDefaults(t *testing.T) {
	tests := []struct {
		value Reasoning
		want  int
	}{
		{ReasoningLow, 2048},
		{ReasoningMedium, 8192},
		{ReasoningHigh, 32768},
		{ReasoningTokens(4096), 4096},
	}
	for _, tt := range tests {
		policy, err := Parse(tt.value)
		if err != nil {
			t.Fatalf("Parse(%q): %v", tt.value, err)
		}
		got, err := BudgetFor(policy, nil, 0)
		if err != nil {
			t.Fatalf("BudgetFor(%q): %v", tt.value, err)
		}
		if got != tt.want {
			t.Fatalf("BudgetFor(%q) = %d, want %d", tt.value, got, tt.want)
		}
	}
}

func TestBudgetForRejectsOverLimitAndUnsupportedNamedValues(t *testing.T) {
	policy, err := Parse(ReasoningTokens(4096))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := BudgetFor(policy, nil, 2048); err == nil {
		t.Fatal("expected over-limit numeric budget to fail")
	}

	policy, err = Parse(ReasoningXHigh)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := BudgetFor(policy, nil, 0); err == nil {
		t.Fatal("expected unsupported extended named value to fail without provider map")
	}
}

func TestBudgetForNamed(t *testing.T) {
	tests := []struct {
		tier Reasoning
		want int
	}{
		{ReasoningLow, 2048},
		{ReasoningMedium, 8192},
		{ReasoningHigh, 32768},
		{ReasoningOff, 0},
		{ReasoningMinimal, 0},
		{ReasoningXHigh, 0},
		{ReasoningMax, 0},
	}
	for _, tt := range tests {
		t.Run(string(tt.tier), func(t *testing.T) {
			got := BudgetForNamed(tt.tier)
			if got != tt.want {
				t.Fatalf("BudgetForNamed(%q) = %d, want %d", tt.tier, got, tt.want)
			}
		})
	}
}

func TestNearestTierForTokens(t *testing.T) {
	tests := []struct {
		tokens int
		want   Reasoning
	}{
		{1, ReasoningLow},
		{2048, ReasoningLow},
		{4095, ReasoningLow},
		// 4096 = geometric midpoint of 2048 and 8192; ties round up → medium
		{4096, ReasoningMedium},
		{4097, ReasoningMedium},
		{8192, ReasoningMedium},
		{16383, ReasoningMedium},
		// 16384 = geometric midpoint of 8192 and 32768; ties round up → high
		{16384, ReasoningHigh},
		{32768, ReasoningHigh},
		{100000, ReasoningHigh},
	}
	for _, tt := range tests {
		t.Run(string(ReasoningTokens(tt.tokens)), func(t *testing.T) {
			got := NearestTierForTokens(tt.tokens)
			if got != tt.want {
				t.Fatalf("NearestTierForTokens(%d) = %q, want %q", tt.tokens, got, tt.want)
			}
		})
	}
}

package fizeau

import (
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/session"
)

// serviceSessionLog is the service-owned writer that persists the session
// lifecycle records (session.start + session.end) for one Execute call. It
// is constructed in runExecute after the route is resolved and torn down in
// a defer on the same goroutine. Sub-paths (runNative, runSubprocess, ...)
// emit the terminal event through finalizeAndEmit, which delegates here to
// keep the session log in sync with the public event stream.
type serviceSessionLog struct {
	logger    *session.Logger
	path      string
	sessionID string
	decision  RouteDecision
	override  *overrideContext
	endOnce   sync.Once
	endWrote  atomic.Bool
	closeOnce sync.Once

	progressMu     sync.Mutex
	lastProgressAt time.Time
}

// openSessionLog creates the session-log writer for req and emits the
// session.start record. A nil-or-empty req.SessionLogDir yields a no-op
// writer so callers don't need to branch on whether logging is enabled.
func (s *service) openSessionLog(req ServiceExecuteRequest, decision RouteDecision, sessionID string) *serviceSessionLog {
	if req.SessionLogDir == "" || sessionID == "" {
		return &serviceSessionLog{}
	}
	logger := session.NewLogger(req.SessionLogDir, sessionID)
	sl := &serviceSessionLog{
		logger:    logger,
		path:      filepath.Join(req.SessionLogDir, sessionID+".jsonl"),
		sessionID: sessionID,
		decision:  decision,
	}
	// CONTRACT-003: echo top-level Role + CorrelationID into the
	// session-log header (one line per session). Top-level wins over
	// any caller Metadata entry under the reserved keys.
	headerMeta := metaWithRoleAndCorrelation(req.Metadata, req.Role, req.CorrelationID)
	start := session.SessionStartData{
		Provider:               s.providerTypeLabel(decision.Provider),
		Model:                  decision.Model,
		SelectedProvider:       decision.Provider,
		SelectedEndpoint:       decision.Endpoint,
		SelectedServerInstance: decision.ServerInstance,
		SelectedRoute:          req.SelectedRoute,
		Sticky: session.RoutingStickyState{
			KeyPresent:     req.CorrelationID != "",
			Assignment:     decision.Sticky.Assignment,
			ServerInstance: decision.Sticky.ServerInstance,
			Reason:         decision.Sticky.Reason,
			Bonus:          decision.Sticky.Bonus,
		},
		Utilization: session.RoutingUtilizationState{
			Source:         decision.Utilization.Source,
			Freshness:      decision.Utilization.Freshness,
			ActiveRequests: decision.Utilization.ActiveRequests,
			QueuedRequests: decision.Utilization.QueuedRequests,
			MaxConcurrency: decision.Utilization.MaxConcurrency,
			CachePressure:  decision.Utilization.CachePressure,
			ObservedAt:     decision.Utilization.ObservedAt,
		},
		RequestedHarness: req.Harness,
		ResolvedHarness:  decision.Harness,
		HarnessSource:    harnessSource(req),
		RequestedModel:   req.Model,
		ResolvedModel:    decision.Model,
		Reasoning:        req.Reasoning,
		WorkDir:          req.WorkDir,
		MaxIterations:    req.MaxIterations,
		Prompt:           req.Prompt,
		SystemPrompt:     req.SystemPrompt,
		Metadata:         headerMeta,
	}
	logger.Emit(agentcore.EventSessionStart, start)
	return sl
}

// writeEnd records the terminal session.end event. It is idempotent: the
// first call wins. Callers should invoke this whenever a harnesses.FinalData
// is produced — finalizeAndEmit threads it together with the public-stream
// emit so the two views stay consistent.
func (sl *serviceSessionLog) writeEnd(req ServiceExecuteRequest, meta map[string]string, final harnesses.FinalData) {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.endOnce.Do(func() {
		sl.endWrote.Store(true)
		end := session.SessionEndData{
			Status:           harnessStatusToCoreStatus(final.Status),
			ProcessOutcome:   processOutcomeForFinal(final.Status),
			Output:           final.FinalText,
			Tokens:           finalUsageToCoreTokens(final.Usage),
			DurationMs:       final.DurationMS,
			SelectedRoute:    req.SelectedRoute,
			SelectedEndpoint: sl.decision.Endpoint,
			Sticky: session.RoutingStickyState{
				KeyPresent:     req.CorrelationID != "",
				Assignment:     sl.decision.Sticky.Assignment,
				ServerInstance: sl.decision.Sticky.ServerInstance,
				Reason:         sl.decision.Sticky.Reason,
				Bonus:          sl.decision.Sticky.Bonus,
			},
			Utilization: session.RoutingUtilizationState{
				Source:         sl.decision.Utilization.Source,
				Freshness:      sl.decision.Utilization.Freshness,
				ActiveRequests: sl.decision.Utilization.ActiveRequests,
				QueuedRequests: sl.decision.Utilization.QueuedRequests,
				MaxConcurrency: sl.decision.Utilization.MaxConcurrency,
				CachePressure:  sl.decision.Utilization.CachePressure,
				ObservedAt:     sl.decision.Utilization.ObservedAt,
			},
			RequestedHarness: req.Harness,
			ResolvedHarness:  "",
			HarnessSource:    harnessSource(req),
			RequestedModel:   req.Model,
			Reasoning:        req.Reasoning,
			Metadata:         meta,
			Error:            final.Error,
		}
		if final.CostUSD > 0 {
			cost := final.CostUSD
			end.CostUSD = &cost
		}
		if req.CostCapUSD > 0 {
			cap := req.CostCapUSD
			end.CostCapUSD = &cap
		}
		if final.RoutingActual != nil {
			end.ResolvedHarness = final.RoutingActual.Harness
			end.Model = final.RoutingActual.Model
			end.SelectedProvider = final.RoutingActual.Provider
			if final.RoutingActual.ServerInstance != "" {
				end.SelectedServerInstance = final.RoutingActual.ServerInstance
			}
			end.ResolvedModel = final.RoutingActual.Model
			end.AttemptedProviders = append([]string(nil), final.RoutingActual.FallbackChainFired...)
			if len(end.AttemptedProviders) > 1 {
				end.FailoverCount = len(end.AttemptedProviders) - 1
			}
		}
		if end.SelectedServerInstance == "" {
			end.SelectedServerInstance = sl.decision.ServerInstance
		}
		sl.logger.Emit(agentcore.EventSessionEnd, end)
	})
}

// writeEvent persists a raw agent event to the session log. Used by the
// native loop callback to capture llm.request / llm.response / tool.call /
// compaction.* events so kept-sandbox bundles preserve a complete trace
// for benchmark reruns and post-mortem debugging. session.start and
// session.end are skipped because writeStart/writeEnd own those records and
// enrich them with service-side routing fields the loop does not see.
func (sl *serviceSessionLog) writeEvent(ev agentcore.Event) {
	if sl == nil || sl.logger == nil {
		return
	}
	switch ev.Type {
	case agentcore.EventSessionStart, agentcore.EventSessionEnd,
		agentcore.EventOverride, agentcore.EventRejectedOverride:
		return
	}
	sl.logger.Write(ev)
}

// writeOverrideEvent persists an override or rejected_override payload to
// the session log so windowed reporting (UsageReport, ADR-006 §5) can
// recompute routing-quality across restarts and beyond the in-memory
// ring's bounded retention. eventType is one of ServiceEventTypeOverride
// / ServiceEventTypeRejectedOverride.
func (sl *serviceSessionLog) writeOverrideEvent(eventType string, payload ServiceOverrideData) {
	if sl == nil || sl.logger == nil {
		return
	}
	payload.SessionID = sl.sessionID
	sl.logger.Emit(agentcore.EventType(eventType), payload)
}

// close flushes the underlying file. Safe to call multiple times.
func (sl *serviceSessionLog) close() {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.closeOnce.Do(func() {
		_ = sl.logger.Close()
	})
}

// endWritten reports whether writeEnd has already recorded a terminal event.
func (sl *serviceSessionLog) endWritten() bool {
	if sl == nil {
		return false
	}
	return sl.endWrote.Load()
}

// persistRejectedOverride writes a session.start + rejected_override pair
// to a freshly-opened session log for sessionID. Used by Execute's
// pre-dispatch rejection branch, which never reaches runExecute and so
// never goes through the normal openSessionLog path. Without this,
// rejected_override events are invisible to UsageReport (which scans
// session logs over a --since window).
//
// The session.start is required by ScanRoutingQuality, which only counts
// log files that include one — and we want this rejection counted in
// TotalRequests so AutoAcceptanceRate reflects reality.
func (s *service) persistRejectedOverride(req ServiceExecuteRequest, sessionID string, payload ServiceOverrideData) {

}

// validateExplicitProvider rejects pre-dispatch when the caller pinned a
// provider name that the service configuration does not recognize. Returns
// nil when no provider was pinned, when no ServiceConfig is configured (no
// provider catalog to validate against), when the provider name is known,
// or when the harness is test-only / does not consume Provider (virtual,
// script, etc. have no real provider lookup).
func validateExplicitProvider(sc ServiceConfig, cfg harnesses.HarnessConfig, provider string) error {
	if provider == "" || sc == nil {
		return nil
	}
	if cfg.TestOnly {
		return nil
	}
	lookup := provider
	if base, _, ok := splitEndpointProviderRef(provider); ok {
		lookup = base
	}
	if _, ok := sc.Provider(lookup); ok {
		return nil
	}
	known := sc.ProviderNames()
	return &ErrUnknownProvider{Provider: provider, KnownProviders: append([]string(nil), known...)}
}

func validateExplicitHarnessModel(name string, cfg harnesses.HarnessConfig, model, provider string) error {
	if model == "" || cfg.TestOnly || cfg.IsHTTPProvider || name == "fiz" {
		return nil
	}
	if modelSupportedForHarness(name, cfg, model, provider) {
		return nil
	}
	supportedModels := subprocessHarnessModelIDs(name, cfg)
	return &ErrHarnessModelIncompatible{
		Harness:         name,
		Model:           model,
		SupportedModels: append([]string(nil), supportedModels...),
	}
}

func modelSupportedForHarness(name string, cfg harnesses.HarnessConfig, model, provider string) bool {
	for _, known := range subprocessHarnessModelIDs(name, cfg) {
		if model == known {
			return true
		}
	}
	switch name {
	case "codex":
		return strings.HasPrefix(model, "gpt-")
	case "claude":
		return strings.HasPrefix(model, "claude-")
	case "pi":
		// Pi can route to non-Gemini backends (lmstudio, omlx, etc.) when a
		// provider is pinned. The pi CLI owns per-provider model validation
		// in that case, so the agent-side gate trusts the provider pin and
		// defers concrete model-ID checks to pi --list-models / pi itself.
		return provider != ""
	case "opencode":
		// OpenCode can route to configured provider/model pairs when the
		// provider is pinned; the generated opencode config and CLI own the
		// concrete model validation in that case.
		return provider != ""
	default:
		return len(cfg.Models) == 0
	}
}

func validateExplicitHarnessReasoning(name string, cfg harnesses.HarnessConfig, value Reasoning) error {
	if cfg.TestOnly {
		return nil
	}
	if len(cfg.ReasoningLevels) == 0 && cfg.MaxReasoningTokens <= 0 {
		return nil
	}
	policy, err := reasoning.ParseString(string(value))
	if err != nil {
		return fmt.Errorf("unsupported reasoning %q for harness %q: %w", value, name, err)
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return nil
	case reasoning.KindTokens:
		if cfg.MaxReasoningTokens <= 0 {
			return fmt.Errorf("unsupported reasoning %q for harness %q; token budgets are not supported", value, name)
		}
		if policy.Tokens > cfg.MaxReasoningTokens {
			return fmt.Errorf("unsupported reasoning %q for harness %q; max token budget is %d", value, name, cfg.MaxReasoningTokens)
		}
		return nil
	case reasoning.KindNamed:
		for _, supported := range cfg.ReasoningLevels {
			if string(policy.Value) == supported {
				return nil
			}
		}
		return fmt.Errorf("unsupported reasoning %q for harness %q; supported reasoning: %s", value, name, strings.Join(cfg.ReasoningLevels, ", "))
	default:
		return fmt.Errorf("unsupported reasoning %q for harness %q", value, name)
	}
}

func harnessSource(req ServiceExecuteRequest) string {
	if strings.TrimSpace(req.Harness) != "" {
		return "request_harness"
	}
	return "auto_route"
}

// runExecute is the per-Execute goroutine. It owns the channel close path
// and the final event emit. All termination paths funnel through emitFinal
// so the channel always sees a final event before close.
func (s *service) runExecute(ctx context.Context, req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, out chan<- ServiceEvent, sessionID string, overrideCtx *overrideContext) {
	defer close(out)

	start := time.Now()
	var seq atomic.Int64

	// Open the service-owned session log writer and guarantee a terminal
	// session.end record plus a clean file close even on unexpected exits.
	// CONTRACT-003 makes session-log lifecycle a service responsibility; the
	// per-path finalizeAndEmit calls below feed writeEnd in lock-step with
	// the public final event.
	sl := s.executeSessionLogOpener().openSessionLog(req, decision, sessionID)
	if overrideCtx != nil {
		sl.override = overrideCtx
	}
	defer func() {
		if !sl.endWritten() {
			sl.writeEnd(req, meta, harnesses.FinalData{
				Status:     "cancelled",
				Error:      "session ended without final event",
				DurationMS: time.Since(start).Milliseconds(),
				RoutingActual: &harnesses.RoutingActual{
					Harness:  decision.Harness,
					Provider: decision.Provider,
					Model:    decision.Model,
				},
			})
		}
		sl.close()
	}()

	// Wall-clock cap.
	runCtx := ctx
	if req.Timeout > 0 {
		var cancel context.CancelFunc
		runCtx, cancel = context.WithTimeout(ctx, req.Timeout)
		defer cancel()
	}

	emitJSON(out, seq, t, meta, payload)
}

// finalizeAndEmit stamps the service-owned session-log path onto final,
// records the terminal session.end event, and forwards the final to the
// public event stream. Every terminal emit path in runExecute funnels
// through this helper so the session log and the event channel stay in
// lock-step (CONTRACT-003).
//
// finalizeAndEmit also performs the CONTRACT-003 echo of top-level Role
// and CorrelationID into the final event Metadata (top-level wins over
// any caller-supplied Metadata entry under the same reserved key) and
// stamps RoutingActual.Power from the catalog projection of the
// actually-dispatched Model. When the caller set both top-level
// Role/CorrelationID and the same reserved Metadata key, a
// MetadataKeyCollision warning is appended to final.Warnings.
func finalizeAndEmit(out chan<- ServiceEvent, seq *atomic.Int64, meta map[string]string, req ServiceExecuteRequest, sl *serviceSessionLog, final harnesses.FinalData) {
	if sl != nil && sl.path != "" {
		final.SessionLogPath = sl.path
	}
	// Stamp catalog power onto the actually-dispatched RoutingActual.
	// final.RoutingActual is set by the caller (one per terminal path);
	// when nil we leave it nil to avoid synthesizing routing evidence.
	if final.RoutingActual != nil && final.RoutingActual.Power == 0 {
		final.RoutingActual.Power = catalogPowerForModel(serviceRoutingCatalog(), final.RoutingActual.Model)
	}
	// Detect reserved metadata-key collisions and append a warning so the
	// caller learns when their caller-supplied Metadata entries were
	// overridden by the top-level Role / CorrelationID fields.
	if collisions := metadataReservedKeyCollisions(req.Metadata, req.Role, req.CorrelationID); len(collisions) > 0 {
		final.Warnings = append(final.Warnings, harnesses.FinalWarning{
			Code:    MetadataWarningCodeKeyCollision,
			Message: metadataKeyCollisionMessage(collisions),
		})
	}
	// Echo Role + CorrelationID onto the final event Metadata.
	finalMeta := metaWithRoleAndCorrelation(meta, req.Role, req.CorrelationID)
	if sl != nil {
		if ovr := sl.override; ovr != nil && !ovr.emitted.Load() {
			sl.writeOverrideEvent(ServiceEventTypeOverride, ovr.payload)
		}
		sl.writeEnd(req, finalMeta, final)
	}
	emitFinal(out, seq, finalMeta, final)
}

package claude

import (
