	BeforeFinal   func(harnesses.FinalData)
	ObserveEvent  func(harnesses.Event) harnesses.Event
	EmitEvent     func(harnesses.Event) bool
	Finalize      func(harnesses.FinalData)
	WriteEnd      func(map[string]string, harnesses.FinalData)
}

// RunSubprocess executes a subprocess harness and forwards its event stream.
func RunSubprocess(ctx context.Context, req SubprocessRequest, runner harnesses.Harness, cb SubprocessCallbacks) {
	hReq := harnesses.ExecuteRequest{
		Prompt:        req.Prompt,
		SystemPrompt:  req.SystemPrompt,
		Provider:      req.Decision.Provider,
		Model:         req.Decision.Model,
		WorkDir:       req.WorkDir,
		Permissions:   req.Permissions,
		Temperature:   subprocessTemperature(req.Temperature),
		Seed:          subprocessSeed(req.Seed),
		Reasoning:     adapterReasoning(req.Reasoning),
		Timeout:       req.Timeout,
		IdleTimeout:   req.IdleTimeout,
		SessionLogDir: req.SessionLogDir,
		Metadata:      req.Metadata,
	}
	if cb.BeforeExecute != nil {
		cb.BeforeExecute()
	}
	in, err := runner.Execute(ctx, hReq)
	if err != nil {
		finalizeSubprocess(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      err.Error(),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:        req.Decision.Harness,
				Provider:       req.Decision.Provider,
				ServerInstance: req.Decision.ServerInstance,
				Model:          req.Decision.Model,
			},
		})
		return
	}
	for ev := range in {
		if ev.Metadata == nil {
			ev.Metadata = req.Metadata
		}
		if ev.Type == harnesses.EventTypeFinal {
			var final harnesses.FinalData
			if err := json.Unmarshal(ev.Data, &final); err == nil && cb.BeforeFinal != nil {
				cb.BeforeFinal(final)
			}
			ev = stampSubprocessFinalRouting(ev, req.Decision)
			ev = stampSubprocessFinalSessionLog(ev, req.SessionLogPath)
			if err := json.Unmarshal(ev.Data, &final); err == nil && cb.WriteEnd != nil {
				cb.WriteEnd(req.Metadata, final)
			}
		}
		if cb.ObserveEvent != nil {
			ev = cb.ObserveEvent(ev)
		}
		if cb.EmitEvent != nil && !cb.EmitEvent(ev) {
			return
		}
	}
}

func subprocessTemperature(v *float32) float32 {
	if v == nil {
		return 0
	}
	return *v
}

func subprocessSeed(v *int64) int64 {
	if v == nil {
		return 0
	}
	return *v
}

func adapterReasoning(value reasoning.Reasoning) string {
	policy, err := reasoning.ParseString(string(value))
	if err != nil {
		return string(value)
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return ""
	case reasoning.KindTokens:
		if policy.Tokens == 0 {
			return ""
		}
		return string(policy.Value)
	case reasoning.KindNamed:
		return string(policy.Value)
	default:
		return string(value)
	}
}

func stampSubprocessFinalSessionLog(ev harnesses.Event, sessionLogPath string) harnesses.Event {
	if sessionLogPath == "" {
		return ev
	}
	var final harnesses.FinalData
	if err := json.Unmarshal(ev.Data, &final); err != nil {
		return ev
	}
	final.SessionLogPath = sessionLogPath
	raw, err := json.Marshal(final)
	if err != nil {
		return ev
	}
	ev.Data = raw
	return ev
}

func stampSubprocessFinalRouting(ev harnesses.Event, decision ExecuteRunnerDecision) harnesses.Event {
	var final harnesses.FinalData
	if err := json.Unmarshal(ev.Data, &final); err != nil {
		return ev
	}
	if final.RoutingActual == nil {
		final.RoutingActual = &harnesses.RoutingActual{
			Harness:        decision.Harness,
			Provider:       decision.Provider,
			ServerInstance: decision.ServerInstance,
			Model:          decision.Model,
		}
	}
	raw, err := json.Marshal(final)
	if err != nil {
		return ev
	}
	ev.Data = raw
	return ev
}

func finalizeSubprocess(cb SubprocessCallbacks, final harnesses.FinalData) {
	if cb.Finalize != nil {
		cb.Finalize(final)
	}
}

package serviceimpl

import (
	"context"
	"fmt"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	claudeharness "github.com/easel/fizeau/internal/harnesses/claude"
	codexharness "github.com/easel/fizeau/internal/harnesses/codex"
	geminiharness "github.com/easel/fizeau/internal/harnesses/gemini"
	opencodeharness "github.com/easel/fizeau/internal/harnesses/opencode"
	piharness "github.com/easel/fizeau/internal/harnesses/pi"
)

// ExecuteDispatchRequest carries API-neutral data needed to choose the
// concrete execute runner.
type ExecuteDispatchRequest struct {
	Decision ExecuteRunnerDecision
	Started  time.Time
}

// ExecuteDispatchCallbacks connect the internal dispatcher to root-owned
// public event/session adapters.
type ExecuteDispatchCallbacks struct {
	RunNative      func(context.Context)
	RunSubprocess  func(context.Context, harnesses.Harness)
	RunVirtual     func(context.Context)
	RunScript      func(context.Context)
	IsHTTPProvider func(harness string) bool
	Finalize       func(harnesses.FinalData)
}

// DispatchExecuteRun selects the concrete runner for an Execute request.
func DispatchExecuteRun(ctx context.Context, req ExecuteDispatchRequest, cb ExecuteDispatchCallbacks) {
	switch req.Decision.Harness {
	case "fiz", "":
		if cb.RunNative != nil {
			cb.RunNative(ctx)
		}
	case "claude":
		runSubprocess(ctx, cb, &claudeharness.Runner{})
	case "codex":
		runSubprocess(ctx, cb, &codexharness.Runner{})
	case "gemini":
		runSubprocess(ctx, cb, &geminiharness.Runner{})
	case "opencode":
		runSubprocess(ctx, cb, &opencodeharness.Runner{})
	case "pi":
		runSubprocess(ctx, cb, &piharness.Runner{})
	case "virtual":
		if cb.RunVirtual != nil {
			cb.RunVirtual(ctx)
		}
	case "script":
		if cb.RunScript != nil {
			cb.RunScript(ctx)
		}
	default:
		if cb.IsHTTPProvider != nil && cb.IsHTTPProvider(req.Decision.Harness) {
			if cb.RunNative != nil {
				cb.RunNative(ctx)
			}
			return
		}
		finalizeDispatch(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      fmt.Sprintf("harness %q dispatch not yet wired in service.Execute", req.Decision.Harness),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:        req.Decision.Harness,
				Provider:       req.Decision.Provider,
				ServerInstance: req.Decision.ServerInstance,
				Model:          req.Decision.Model,
			},
		})
	}
}

func runSubprocess(ctx context.Context, cb ExecuteDispatchCallbacks, runner harnesses.Harness) {
	if cb.RunSubprocess != nil {
		cb.RunSubprocess(ctx, runner)
	}
}

func finalizeDispatch(cb ExecuteDispatchCallbacks, final harnesses.FinalData) {
	if cb.Finalize != nil {
		cb.Finalize(final)
	}
}
package serviceimpl

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/harnesses"
)

const (
	defaultStallReadOnlyIterations = 25
	defaultMaxIterations           = 200
)

var nativeReadOnlyTools = map[string]bool{
	"read":       true,
	"read_file":  true,
	"grep":       true,
	"ls":         true,
	"find":       true,
	"cat":        true,
	"head":       true,
	"tail":       true,
	"stat":       true,
	"web_fetch":  true,
	"web_search": true,
}

// NativeDecision is the API-neutral routing data needed by the native runner.
type NativeDecision struct {
	Harness        string
	Provider       string
	ServerInstance string
	Model          string
	Candidates     []NativeRouteCandidate
}

// NativeRouteCandidate is the API-neutral subset of root RouteCandidate used
// by the native failover provider.
type NativeRouteCandidate struct {
	Provider       string
	Endpoint       string
	ServerInstance string
	Model          string
	Eligible       bool
}

// NativeRequest is the API-neutral request data needed by the native runner.
type NativeRequest struct {
	Prompt                    string
	SystemPrompt              string
	Model                     string
	Provider                  string
	Harness                   string
	WorkDir                   string
	Temperature               *float32
	TopP                      *float64
	TopK                      *int
	MinP                      *float64
	RepetitionPenalty         *float64
	Seed                      *int64
	SamplingSource            string
	Reasoning                 agentcore.Reasoning
	NoStream                  bool
	Permissions               string
	Tools                     []agentcore.Tool
	ToolPreset                string
	PlanningMode              bool
	MaxIterations             int
	MaxTokens                 int
	ReasoningByteLimit        int
	ProviderTimeout           time.Duration
	Timeout                   time.Duration
	CachePolicy               string
	StallMaxReadOnlyIteration *int
	Metadata                  map[string]string
	Decision                  NativeDecision
	Started                   time.Time
	SessionID                 string
	// CostCapUSD mirrors ServiceExecuteRequest.CostCapUSD. See
	// internal/core.Request.CostCapUSD for the enforcement contract.
	CostCapUSD float64
}

// NativeProviderRequest is the narrow provider-selection request that crosses
// from the internal runner back into root-owned provider configuration.
type NativeProviderRequest struct {
	Provider string
	Harness  string
	Model    string
}

// NativeProviderResolution is the API-neutral result of root-owned provider
// construction.
type NativeProviderResolution struct {
	Provider agentcore.Provider
	Name     string
	Model    string
}

// NativeCallbacks are root-owned service seams used by the internal runner
// without importing root public contract types.
type NativeCallbacks struct {
	ResolveProvider            func(NativeProviderRequest) NativeProviderResolution
	ProviderNotConfiguredError func(NativeProviderRequest, NativeDecision) string
	Compactor                  func(model string) agentcore.Compactor
	ObserveAgentEvent          func(agentcore.Event)
	EmitEvent                  func(harnesses.EventType, any)
	BeforeFinal                func(harnesses.FinalData)
	Finalize                   func(harnesses.FinalData)
	ToolWiringHook             func(harness string, toolNames []string)
	PromptAssertionHook        func(systemPrompt, prompt string, contextFiles []string)
	CompactionAssertionHook    func(messagesBefore, messagesAfter, tokensFreed int)
	ObserveTokenUsage          func(provider string, tokens int, at time.Time)
}

// RunNative drives the in-process agent loop without depending on root public
// service types.
func RunNative(ctx context.Context, req NativeRequest, cb NativeCallbacks) {
	provider := nativeExecutionProvider(req, cb.ResolveProvider)
	actualHarness := req.Decision.Harness
	if actualHarness == "" {
		actualHarness = "fiz"
	}
	resolvedProvider := resolveProvider(cb.ResolveProvider, nativeProviderRequest(req, req.Decision))
	actualProvider := resolvedProvider.Name
	if actualProvider == "" {
		actualProvider = req.Decision.Provider
	}
	actualModel := req.Decision.Model
	if actualModel == "" {
		actualModel = resolvedProvider.Model
	}
	if provider == nil {
		finalize(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      providerNotConfiguredError(cb.ProviderNotConfiguredError, req, req.Decision),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:        actualHarness,
				Provider:       actualProvider,
				ServerInstance: req.Decision.ServerInstance,
				Model:          actualModel,
			},
		})
		return
	}
	permission, permissionErr := nativePermissionMode(req.Permissions)
	if permissionErr != nil {
		finalize(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      permissionErr.Error(),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:        actualHarness,
				Provider:       actualProvider,
				ServerInstance: req.Decision.ServerInstance,
				Model:          actualModel,
			},
		})
		return
	}

	if req.ProviderTimeout > 0 {
		provider = wrapProviderRequestTimeout(provider, req.ProviderTimeout)
	}

	policyMax := defaultStallReadOnlyIterations
	if req.StallMaxReadOnlyIteration != nil {
		policyMax = *req.StallMaxReadOnlyIteration
	}
	maxIter := req.MaxIterations
	if maxIter <= 0 {
		maxIter = defaultMaxIterations
	}

	var (
		readOnlyStreak atomic.Int64
		stalled        atomic.Bool
		stallReason    atomic.Value
		stallCount     atomic.Int64
	)
	cancelCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	loopCB := func(ev agentcore.Event) {
		if cb.ObserveAgentEvent != nil {
			cb.ObserveAgentEvent(ev)
		}
		switch ev.Type {
		case agentcore.EventToolCall:
			var payload nativeToolCallPayload
			_ = json.Unmarshal(ev.Data, &payload)
			if !toolLikelyMakesProgress(payload.Tool, payload) {
				if v := readOnlyStreak.Add(1); policyMax > 0 && int(v) >= policyMax {
					if stalled.CompareAndSwap(false, true) {
						stallReason.Store("no_progress_tools_exceeded")
						stallCount.Store(v)
						cancel()
					}
				}
			} else {
				readOnlyStreak.Store(0)
			}
		case agentcore.EventCompactionEnd:
			if cb.CompactionAssertionHook != nil {
				var payload nativeCompactionPayload
				_ = json.Unmarshal(ev.Data, &payload)
				cb.CompactionAssertionHook(payload.MessagesBefore, payload.MessagesAfter, payload.TokensBefore-payload.TokensAfter)
			}
		}
	}

	tools := filterNativeToolsForPermission(req.Tools, permission)
	if cb.ToolWiringHook != nil {
		cb.ToolWiringHook(req.Decision.Harness, ToolNames(tools))
	}
	if cb.PromptAssertionHook != nil {
		cb.PromptAssertionHook(req.SystemPrompt, req.Prompt, nil)
	}

	var compactor agentcore.Compactor
	if cb.Compactor != nil {
		compactor = cb.Compactor(actualModel)
	}
	var temperature *float64
	if req.Temperature != nil {
		t := float64(*req.Temperature)
		temperature = &t
	}
	var seed int64
	if req.Seed != nil {
		seed = *req.Seed
	}
	loopReq := agentcore.Request{
		Prompt:             req.Prompt,
		SystemPrompt:       req.SystemPrompt,
		Provider:           provider,
		Tools:              tools,
		WorkDir:            req.WorkDir,
		Callback:           loopCB,
		Metadata:           req.Metadata,
		MaxIterations:      maxIter,
		ResolvedModel:      actualModel,
		SelectedProvider:   actualProvider,
		Temperature:        temperature,
		TopP:               req.TopP,
		TopK:               req.TopK,
		MinP:               req.MinP,
		RepetitionPenalty:  req.RepetitionPenalty,
		Seed:               seed,
		SamplingSource:     req.SamplingSource,
		Reasoning:          req.Reasoning,
		NoStream:           req.NoStream,
		MaxTokens:          req.MaxTokens,
		ReasoningByteLimit: req.ReasoningByteLimit,
		Compactor:          compactor,
		CachePolicy:        req.CachePolicy,
		PlanningMode:       req.PlanningMode || req.ToolPreset == "benchmark",
		CostCapUSD:         req.CostCapUSD,
	}
	result, runErr := agentcore.Run(cancelCtx, loopReq)
	if shouldRetryNativeNoStream(req.NoStream, result, runErr) {
		loopReq.NoStream = true
		result, runErr = agentcore.Run(cancelCtx, loopReq)
	}

	finalProvider := actualProvider
	if result.SelectedProvider != "" {
		finalProvider = result.SelectedProvider
	}
	finalModel := actualModel
	if result.ResolvedModel != "" {
		finalModel = result.ResolvedModel
	}
	final := harnesses.FinalData{
		DurationMS: time.Since(req.Started).Milliseconds(),
		FinalText:  result.Output,
		RoutingActual: &harnesses.RoutingActual{
			Harness:            actualHarness,
			Provider:           finalProvider,
			ServerInstance:     req.Decision.ServerInstance,
			Model:              finalModel,
			FallbackChainFired: append([]string(nil), result.AttemptedProviders...),
		},
	}
	final.Usage = &harnesses.FinalUsage{
		InputTokens:      harnesses.IntPtr(result.Tokens.Input),
		OutputTokens:     harnesses.IntPtr(result.Tokens.Output),
		CacheReadTokens:  nil,
		CacheWriteTokens: nil,
		TotalTokens:      harnesses.IntPtr(result.Tokens.Total),
		Source:           harnesses.UsageSourceFallback,
	}
	if result.Tokens.CacheRead > 0 {
		final.Usage.CacheReadTokens = harnesses.IntPtr(result.Tokens.CacheRead)
	}
	if result.Tokens.CacheWrite > 0 {
		final.Usage.CacheWriteTokens = harnesses.IntPtr(result.Tokens.CacheWrite)
	}
	if result.Tokens.CacheRead > 0 || result.Tokens.CacheWrite > 0 {
		final.Usage.CacheTokens = harnesses.IntPtr(result.Tokens.CacheRead + result.Tokens.CacheWrite)
	}
	if result.CostUSD > 0 {
		final.CostUSD = result.CostUSD
	}
	if result.Output != "" && cb.EmitEvent != nil {
		cb.EmitEvent(harnesses.EventTypeTextDelta, harnesses.TextDeltaData{Text: result.Output})
	}
	if cb.BeforeFinal != nil {
		cb.BeforeFinal(final)
	}
	switch {
	case stalled.Load():
		final.Status = "stalled"
		reason, _ := stallReason.Load().(string)
		if cb.EmitEvent != nil {
			cb.EmitEvent(harnesses.EventTypeStall, map[string]any{
				"reason": reason,
				"count":  stallCount.Load(),
			})
		}
		final.Error = reason
	case ctx.Err() == context.DeadlineExceeded || (req.Timeout > 0 && time.Since(req.Started) >= req.Timeout):
		final.Status = "timed_out"
		final.Error = "wall-clock timeout"
	case ctx.Err() == context.Canceled:
		final.Status = "cancelled"
	case runErr != nil:
		final.Status = "failed"
		final.Error = runErr.Error()
	case result.Status == agentcore.StatusError:
		final.Status = "failed"
		if result.Error != nil {

			input := payload.Input
			if input == nil {
				if rawIn, err := json.Marshal(map[string]any{"tool": toolName}); err == nil {
					input = rawIn
				}
			}
			callID := fmt.Sprintf("call-%d", ev.Seq)
			_, completeProgress := progress.noteToolCall(callID, payload)
			emitJSONRaw(out, seq, harnesses.EventTypeToolCall, meta, harnesses.ToolCallData{
				ID:    callID,
				Name:  toolName,
				Input: input,
			})
			emitJSONRaw(out, seq, harnesses.EventTypeToolResult, meta, harnesses.ToolResultData{
				ID:         callID,
				Output:     payload.Output,
				Error:      payload.Error,
				DurationMS: payload.DurationMS,
			})
			emitProgress(out, seq, sl, sessionID, meta, completeProgress)
		case agentcore.EventCompactionEnd:
			var payload nativeCompactionPayload
			_ = json.Unmarshal(ev.Data, &payload)
			emitJSONRaw(out, seq, harnesses.EventTypeCompaction, meta, map[string]any{
				"messages_before": payload.MessagesBefore,
				"messages_after":  payload.MessagesAfter,
				"tokens_freed":    payload.TokensBefore - payload.TokensAfter,
			})
			compactionProgress, contextProgress := progress.noteCompaction(payload)
			emitProgress(out, seq, sl, sessionID, meta, compactionProgress)
			emitProgress(out, seq, sl, sessionID, meta, contextProgress)
		}
	}

	var stallMaxReadOnlyIterations *int
	if req.StallPolicy != nil {
		stallMaxReadOnlyIterations = &req.StallPolicy.MaxReadOnlyToolIterations
	}
	serviceimpl.RunNative(ctx, serviceimpl.NativeRequest{
		Prompt:                    req.Prompt,
		SystemPrompt:              req.SystemPrompt,
		Model:                     req.Model,
		Provider:                  req.Provider,
		Harness:                   req.Harness,
		WorkDir:                   req.WorkDir,
		Temperature:               req.Temperature,
		TopP:                      req.TopP,
		TopK:                      req.TopK,
		MinP:                      req.MinP,
		RepetitionPenalty:         req.RepetitionPenalty,
		Seed:                      req.Seed,
		SamplingSource:            req.SamplingSource,
		Reasoning:                 effectiveReasoning(req.Reasoning),
		NoStream:                  req.NoStream,
		Permissions:               req.Permissions,
		Tools:                     nativeToolsForRequest(req),
		ToolPreset:                req.ToolPreset,
		PlanningMode:              req.PlanningMode,
		MaxIterations:             req.MaxIterations,
		MaxTokens:                 req.MaxTokens,
		ReasoningByteLimit:        req.ReasoningByteLimit,
		ProviderTimeout:           req.ProviderTimeout,
		Timeout:                   req.Timeout,
		CachePolicy:               req.CachePolicy,
		CostCapUSD:                req.CostCapUSD,
		StallMaxReadOnlyIteration: stallMaxReadOnlyIterations,
		Metadata:                  meta,
		Decision:                  nativeDecision(decision),
		Started:                   start,
		SessionID:                 sessionID,
	}, serviceimpl.NativeCallbacks{
		ResolveProvider: func(nreq serviceimpl.NativeProviderRequest) serviceimpl.NativeProviderResolution {
			resolved := s.resolveNativeProvider(ServiceExecuteRequest{
				Provider: nreq.Provider,
				Harness:  nreq.Harness,
				Model:    nreq.Model,
			})
			return serviceimpl.NativeProviderResolution{
				Provider: resolved.Provider,
				Name:     resolved.Name,
				Model:    resolved.Entry.Model,
			}
		},
		ProviderNotConfiguredError: func(nreq serviceimpl.NativeProviderRequest, ndecision serviceimpl.NativeDecision) string {
			return s.nativeProviderNotConfiguredError(ServiceExecuteRequest{
				Provider: nreq.Provider,
				Harness:  nreq.Harness,
				Model:    nreq.Model,
			}, routeDecision(ndecision))
		},
		Compactor: func(model string) agentcore.Compactor {
			return newServiceCompactor(req, model)
		},
		ObserveAgentEvent: observeAgentEvent,
		EmitEvent: func(t harnesses.EventType, payload any) {
			emitJSONRaw(out, seq, t, meta, payload)
		},
		BeforeFinal: func(final harnesses.FinalData) {
			if progressFinal := progress.noteFinal(final); progressFinal != nil {
				emitProgress(out, seq, sl, sessionID, meta, *progressFinal)
			}
		},
		Finalize: func(final harnesses.FinalData) {
			finalizeAndEmit(out, seq, meta, req, sl, final)
		},
		ToolWiringHook:          s.toolWiringHook(),
		PromptAssertionHook:     s.promptAssertionHook(),
		CompactionAssertionHook: s.compactionAssertionHook(),
		ObserveTokenUsage:       s.observeTokenUsage,
	})
}

func nativeDecision(decision RouteDecision) serviceimpl.NativeDecision {
	return serviceimpl.NativeDecision{
		Harness:        decision.Harness,
		Provider:       decision.Provider,
		ServerInstance: decision.ServerInstance,
		Model:          decision.Model,
		Candidates:     nativeRouteCandidates(decision.Candidates),
	}
}

func routeDecision(decision serviceimpl.NativeDecision) RouteDecision {
	return RouteDecision{
		Harness:        decision.Harness,
		Provider:       decision.Provider,
		ServerInstance: decision.ServerInstance,
		Model:          decision.Model,
	}
}

func nativeRouteCandidates(in []RouteCandidate) []serviceimpl.NativeRouteCandidate {
	if len(in) == 0 {
		return nil
	}
	out := make([]serviceimpl.NativeRouteCandidate, len(in))
	for i, candidate := range in {
		out[i] = serviceimpl.NativeRouteCandidate{
			Provider:       candidate.Provider,
			Endpoint:       candidate.Endpoint,
			ServerInstance: candidate.ServerInstance,
			Model:          candidate.Model,
			Eligible:       candidate.Eligible,
		}
	}
	return out
}

func newServiceCompactor(req ServiceExecuteRequest, model string) agentcore.Compactor {
	cfg := compaction.DefaultConfig()
	if req.CompactionContextWindow > 0 {
		cfg.ContextWindow = req.CompactionContextWindow
		if cfg.ReserveTokens >= cfg.ContextWindow {
			cfg.ReserveTokens = 0
		}
		if cfg.KeepRecentTokens > cfg.ContextWindow {
			cfg.KeepRecentTokens = cfg.ContextWindow / 2
		}
	}
	if req.CompactionReserveTokens > 0 {
		cfg.ReserveTokens = req.CompactionReserveTokens
	}
