// overrideAxis* enumerates the three independently-tracked override axes.
const (
	overrideAxisHarness  = "harness"
	overrideAxisProvider = "provider"
	overrideAxisModel    = "model"
)

// overrideContext carries the per-Execute override-event payload from the
// service entrypoint through to the channel-fan-out goroutine, where the
// terminal outcome is stamped on right before the final event is forwarded.
//
// record points at the live in-memory ring entry for this request (set by
// Execute via recordRoutingQualityForRequest); the fan-out goroutine
// back-writes the outcome onto it when the override event fires so
// RouteStatus surfaces non-zero outcome aggregates.
type overrideContext struct {
	payload ServiceOverrideData
	emitted atomic.Bool
	record  *routingQualityRecord
}

// axesOverridden returns the canonical, ordered list of axes the caller
// pinned. Order is fixed (harness, provider, model) so consumers can
// compare across requests.
func axesOverridden(req ServiceExecuteRequest) []string {
	axes := make([]string, 0, 3)
	if req.Harness != "" {
		axes = append(axes, overrideAxisHarness)
	}
	if req.Provider != "" {
		axes = append(axes, overrideAxisProvider)
	}
	if req.Model != "" {
		axes = append(axes, overrideAxisModel)
	}
	return axes
}

// buildOverrideContext computes the override event payload for req, including
// the second (axes-stripped) ResolveRoute call. Returns nil when no override
// axis is set on the request.
//
// The auto-decision call is best-effort: if it fails (e.g., empty inputs
// after stripping leave nothing to resolve), the auto_decision and component
// fields are left zero. The override event still fires per ADR-006 §7.
func (s *service) buildOverrideContext(ctx context.Context, req ServiceExecuteRequest) *overrideContext {
	axes := axesOverridden(req)
	if len(axes) == 0 {
		return nil
	}

	userPin := ServiceOverridePin{
		Harness:  req.Harness,
		Provider: req.Provider,
		Model:    req.Model,
	}

	auto, autoScore, autoComps := s.resolveAutoDecisionForOverride(ctx, req, axes)

	matchPerAxis := make(map[string]bool, len(axes))
	for _, axis := range axes {
		switch axis {
		case overrideAxisHarness:
			matchPerAxis[axis] = userPin.Harness != "" && userPin.Harness == auto.Harness
		case overrideAxisProvider:
			matchPerAxis[axis] = userPin.Provider != "" && userPin.Provider == auto.Provider
		case overrideAxisModel:
			matchPerAxis[axis] = userPin.Model != "" && userPin.Model == auto.Model

// RouteStatusReport is returned by RouteStatus.
//
// RoutingQuality (ADR-006 §5) is the operator-facing measure of how often
// auto-routing produces an acceptable decision. It is intentionally
// distinct from per-(provider, model) provider-reliability surfaced on
// each RouteCandidateStatus: the two compose, and conflating them is the
// UI bug ADR-006 fixes.
type RouteStatusReport struct {
	Routes          []RouteStatusEntry
	GeneratedAt     time.Time
	GlobalCooldowns []CooldownState
	// RoutingQuality holds the three first-class routing-quality metrics
	// over a recent window (last RouteStatusRoutingQualityWindow requests).
	RoutingQuality RoutingQualityMetrics
}

// RouteStatusRoutingQualityWindow caps how many recent Execute calls
// contribute to RouteStatusReport.RoutingQuality. ADR-006 §5 calls for a
// "recent window"; the constant is exported so operator UIs can label the
// metric appropriately.
const RouteStatusRoutingQualityWindow = 100

// RouteStatusEntry describes the live provider candidates serving one model.
type RouteStatusEntry struct {
	Model                  string
	Strategy               string // informational; route tables are not user-authored
	SelectedEndpoint       string
	SelectedServerInstance string
	Sticky                 RouteStickyState
	Candidates             []RouteCandidateStatus
	LastDecision           *RouteDecision // most recent ResolveRoute result for this key (cached)
	LastDecisionAt         time.Time
}

// RouteCandidateStatus describes a single live provider/model candidate.
//
// ProviderReliabilityRate is the per-(provider, model) observed completion
// rate (the legacy "success rate" metric). Per ADR-006 §5 it is labeled
// "provider reliability" to distinguish it from RoutingQualityMetrics on
// the parent report — the two metrics measure different things and are
// surfaced as separate fields.
type RouteCandidateStatus struct {
	Provider                string
	Model                   string
	ServerInstance          string
	Priority                int
	Healthy                 bool
	Cooldown                *CooldownState
	RecentLatencyMS         float64 // observation-derived; 0 when unavailable
	ProviderReliabilityRate float64 // 0-1; 0 when unavailable. Legacy success-rate field, relabeled per ADR-006 §5 to disambiguate from routing-quality.
}

// ServiceEvent is a contract-level event (mirrors harnesses.Event).
type ServiceEvent = harnesses.Event

// ServiceExecuteRequest is the public ExecuteRequest type per CONTRACT-003.
// See docs/helix/02-design/contracts/CONTRACT-003-fizeau-service.md
// (§"Public types") for the canonical shape; this struct is its in-process
// twin under the agent module.
type ServiceExecuteRequest struct {
	Prompt            string
	SystemPrompt      string
	Model             string
	Provider          string
	Harness           string
	Policy            string
	WorkDir           string
	Temperature       *float32
	TopP              *float64
	TopK              *int
	MinP              *float64
	RepetitionPenalty *float64
	Seed              *int64
	// SamplingSource is the comma-separated layer attribution produced by
	// internal/sampling.Resolve. Plumbed through to the llm.request
	// telemetry event for ADR-007 override-tracking; never on the wire.
	SamplingSource string
	Reasoning      Reasoning
	NoStream       bool
	Permissions    string
	// Tools overrides the built-in native agent tool set when Harness is
	// "fiz". Nil uses the native built-ins for ToolPreset and WorkDir.
	Tools []Tool
	// ToolPreset is passed through to BuiltinToolsForPreset when Tools is nil.
	// Empty uses the default tool set.
	ToolPreset string

	// PlanningMode, when true, performs one no-tool LLM "planning" call
	// before the main native agent loop and injects the response as an
	// assistant message wrapped in <plan> tags. The benchmark tool preset
	// auto-enables planning; this flag is the per-request opt-in for other
	// callers (e.g. the CLI --plan flag). Only honored when Harness=="fiz"
	// (the native loop). See internal/core.Request.PlanningMode.
	PlanningMode bool

package fizeau

import (
	"context"
	"time"

	"github.com/easel/fizeau/internal/routehealth"
	"github.com/easel/fizeau/internal/serverinstance"
)

// RouteStatus returns live routing state for configured providers/models.
// It is the operator dashboard view: cooldowns, recent decisions, and
// per-candidate health. Distinct from per-request ResolveRoute.
func (s *service) RouteStatus(ctx context.Context) (*RouteStatusReport, error) {
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	sc := s.opts.ServiceConfig
	report := &RouteStatusReport{
		GeneratedAt: time.Now(),
	}
	// ADR-006 §5: populate routing-quality over a recent window
	// (RouteStatusRoutingQualityWindow) regardless of whether a route
	// catalog is configured — the metric reflects Execute traffic, not
	// configured routes.
	if s != nil && s.routingQuality != nil {
		recent := s.routingQuality.snapshotRecent(RouteStatusRoutingQualityWindow, time.Time{})
		report.RoutingQuality = computeRoutingQualityMetricsFromRecords(recent)
	}
	if sc == nil {
		return report, nil
	}

	cooldown := s.routeAttemptTTL()
	activeAttempts := s.activeRouteAttempts(report.GeneratedAt, cooldown)

	entries := make(map[string]*RouteStatusEntry)
	order := make([]string, 0)
	for i, providerName := range sc.ProviderNames() {
		provider, ok := sc.Provider(providerName)
		if !ok {
			continue
		}
		model := provider.Model
		if model == "" {
			model = providerName
		}
		entry, ok := entries[model]
		if !ok {
			entry = &RouteStatusEntry{Model: model, Strategy: "auto"}
			if cached, ok := s.lookupRouteDecision(model); ok {
				entry.LastDecision = cached.decision
				entry.LastDecisionAt = cached.at
				entry.SelectedEndpoint = cached.decision.Endpoint
				entry.SelectedServerInstance = cached.decision.ServerInstance
				entry.Sticky = cached.decision.Sticky
			}
			entries[model] = entry
			order = append(order, model)
		}
		cs := RouteCandidateStatus{
			Provider:       providerName,
			Model:          model,
			ServerInstance: serverinstance.Normalize(provider.BaseURL, provider.ServerInstance),
			Priority:       len(sc.ProviderNames()) - i,
		}
		if attemptCooldown := routeAttemptCandidateCooldown(activeAttempts, providerName, model, cooldown); attemptCooldown != nil {
			cs.Cooldown = attemptCooldown
		}
		cs.Healthy = cs.Cooldown == nil
		entry.Candidates = append(entry.Candidates, cs)
	}

	report.Routes = make([]RouteStatusEntry, 0, len(order))
	for _, model := range order {
		report.Routes = append(report.Routes, *entries[model])
	}

	return report, nil
}

func routeAttemptCandidateCooldown(records []routehealth.Record, providerName, model string, cooldown time.Duration) *CooldownState {
	var newest *routehealth.Record
	for i := range records {
		record := &records[i]
		if record.Key.Provider == "" {
			continue
		}
		if providerName != "" && record.Key.Provider != providerName {
			continue
		}
		if record.Key.Model != "" && model != "" && record.Key.Model != model {
			continue
		}
		if newest == nil || record.RecordedAt.After(newest.RecordedAt) {
			newest = record
		}
	}
	if newest == nil {
		return nil
	}
	return routeAttemptCooldown(*newest, cooldown)
}

