// Called by ResolveRoute after a successful resolution.
func (s *service) cacheRouteDecision(routeKey string, dec *RouteDecision) {
	if routeKey == "" || dec == nil {
		return
	}
	s.lastDecisionMu.Lock()
	defer s.lastDecisionMu.Unlock()

// bounds are unset or coherent. Zero means "unset"; positive values are on
// the catalog's 1-10 power scale.
func ValidatePowerBounds(minPower, maxPower int) error {
	if minPower < 0 {
		return fmt.Errorf("invalid MinPower %d: must be >= 0", minPower)
	}
	if maxPower < 0 {
		return fmt.Errorf("invalid MaxPower %d: must be >= 0", maxPower)
	}
	if minPower > 0 && maxPower > 0 && maxPower < minPower {
		return fmt.Errorf("invalid power bounds: MaxPower %d must be >= MinPower %d", maxPower, minPower)
	}
	return nil
}

// RouteDecision is the result of ResolveRoute.
type RouteDecision struct {
	// RequestedPolicy is the caller-supplied policy, when any.
	RequestedPolicy string
	// PowerPolicy records the effective policy inputs used for this
	// resolution. It stays separate from the chosen model so operator
	// surfaces can explain policy without re-deriving it.
	PowerPolicy RoutePowerPolicy
	// Harness is the selected harness name.
	Harness string
	// Provider is the selected provider for native agent routes.
	Provider string
	// Endpoint is the selected named endpoint when the provider exposes more
	// than one endpoint.
	Endpoint string
	// ServerInstance is the normalized server identity used for sticky
	// affinity and route evidence.
	ServerInstance string
	// Model is the selected concrete model.
	Model string
	// Reason summarizes why the selected candidate won.
	Reason string
	// Sticky captures whether this decision reused an existing sticky lease
	// or created a new one.
	Sticky RouteStickyState
	// Utilization captures the endpoint sample that informed the selected
	// candidate, when known.
	Utilization RouteUtilizationState
	// Power is the catalog-projected power of the selected Model
	// (per CONTRACT-003 § Catalog Power Projection). 0 means
	// unknown/exact-pin-only/no catalog entry. DDx callers read this
	// to compute next-attempt MinPower without importing catalog code.
	Power int
	// Candidates is the full ranked decision trace, including rejected
	// candidates and their rejection reasons.
	Candidates []RouteCandidate
}

// RoutePowerPolicy captures the numeric power-policy inputs associated with
// one ResolveRoute call.
type RoutePowerPolicy struct {
	PolicyName string
	MinPower   int
	MaxPower   int
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/provider/utilization"
	"github.com/easel/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// fiz-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	if req.Harness != "" && req.Model != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
			return nil, err
		}
	}
	if req.Harness != "" && req.Policy != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessPolicy(canonical, cfg, req.Policy); err != nil {
			return nil, err
		}
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	requestedPolicy := req.Policy
	policy := routingPolicyForName(cat, requestedPolicy)
	powerPolicy := routePowerPolicyForRequest(cat, req)
	providerPreference, err := providerPreferenceForPolicy(cat, requestedPolicy)
	if err != nil {
		return &RouteDecision{
			RequestedPolicy: req.Policy,
			PowerPolicy:     powerPolicy,
		}, err
	}
	in := s.buildRoutingInputsWithCatalog(ctx, cat)

	resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
	if modelErr != nil {
		result := &RouteDecision{
			RequestedPolicy: req.Policy,
			PowerPolicy:     powerPolicy,
			Candidates:      modelCandidates,
		}
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(modelErr, result.Candidates, req.Policy)
	}

	rReq := routing.Request{
		Policy:                policy,
		Model:                 resolvedModel,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		CorrelationID:         req.CorrelationID,
		AllowLocal:            req.AllowLocal,
		Require:               append([]string(nil), req.Require...),
	}
	if policyEntry, _, ok := policyForName(cat, requestedPolicy); ok {
		rReq.AllowLocal = rReq.AllowLocal || policyEntry.AllowLocal
		rReq.Require = append(append([]string(nil), policyEntry.Require...), rReq.Require...)
	}
	rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
