package reasoning

import (
	"log/slog"
	"math"
	"strings"
)

const (
	ResolutionSourceCaller  = "caller"
	ResolutionSourceSnapped = "snapped"
	ResolutionSourceDefault = "default"
)

type EffortResolution struct {
	Requested string
	Effort    string
	Source    string
	Warning   string
}

type EffortResolveOptions struct {
	Harness            string
	DiscoverySource    string
	SuppressWarningLog bool
}

func ResolveEffortForLevels(value string, supported []string, opts EffortResolveOptions) EffortResolution {
	resolution := EffortResolution{
		Requested: strings.TrimSpace(value),
		Source:    ResolutionSourceDefault,
	}

	policy, err := ParseString(value)
	if err != nil {
		resolution.Effort = strings.TrimSpace(value)
		resolution.Source = ResolutionSourceCaller
		return resolution
	}

	switch policy.Kind {
	case KindUnset, KindAuto, KindOff:
		return resolution
	case KindTokens:
		if policy.Tokens == 0 {
			return resolution
		}
		if len(supported) == 0 {
			resolution.Effort = string(policy.Value)
			resolution.Source = ResolutionSourceCaller
			return resolution
		}
		return validateResolvedTier(NearestTierForTokens(policy.Tokens), policy.Value, supported, opts)
	case KindNamed:
		if len(supported) == 0 {
			resolution.Effort = string(policy.Value)
			resolution.Source = ResolutionSourceCaller
			return resolution
		}
		return validateResolvedTier(policy.Value, policy.Value, supported, opts)
	default:
		resolution.Effort = strings.TrimSpace(value)
		resolution.Source = ResolutionSourceCaller
		return resolution
	}
}

func validateResolvedTier(tier, requested Reasoning, supported []string, opts EffortResolveOptions) EffortResolution {
	resolution := EffortResolution{
		Requested: string(requested),
		Effort:    string(tier),
		Source:    ResolutionSourceCaller,
	}
	if containsReasoning(supported, tier) {
		if tier != requested {
			resolution.Source = ResolutionSourceSnapped
		}
		return resolution
	}

	snapped, ok := nearestSupportedTier(tier, supported)
	if !ok {
		return resolution
	}
	resolution.Effort = string(snapped)
	resolution.Source = ResolutionSourceSnapped
	resolution.Warning = "requested reasoning effort is not supported by harness discovery; snapped to nearest supported tier"
	if !opts.SuppressWarningLog {
		slog.Warn(resolution.Warning,
			"harness", opts.Harness,
			"requested", string(requested),
			"resolved", resolution.Effort,
			"supported", append([]string(nil), supported...),
			"discovery_source", opts.DiscoverySource,
		)
	}
	return resolution
}

func containsReasoning(levels []string, want Reasoning) bool {
	for _, level := range levels {
		if strings.EqualFold(strings.TrimSpace(level), string(want)) {
			return true
		}
	}
	return false
}

func nearestSupportedTier(target Reasoning, supported []string) (Reasoning, bool) {
	best := Reasoning("")
	bestDistance := math.Inf(1)
	for _, raw := range supported {
		policy, err := ParseString(raw)
		if err != nil || policy.Kind != KindNamed {
			continue
		}
		distance, ok := tierDistance(target, policy.Value)
		if !ok {
			continue
		}
		if best == "" || distance < bestDistance || (distance == bestDistance && tierRank(policy.Value) > tierRank(best)) {
			best = policy.Value
			bestDistance = distance
		}
	}
	return best, best != ""
}

func tierDistance(a, b Reasoning) (float64, bool) {
	ab, aOK := portableBudgetForDistance(a)
	bb, bOK := portableBudgetForDistance(b)
	if aOK && bOK {
		return math.Abs(math.Log2(float64(ab)) - math.Log2(float64(bb))), true
	}
	ar := tierRank(a)
	br := tierRank(b)
	if ar == 0 || br == 0 {
		return 0, false
	}
	return math.Abs(float64(ar - br)), true
}

func portableBudgetForDistance(tier Reasoning) (int, bool) {
	budget := BudgetForNamed(tier)
	return budget, budget > 0
}

func tierRank(tier Reasoning) int {
	switch tier {
	case ReasoningMinimal:
		return 1
	case ReasoningLow:
		return 2
	case ReasoningMedium:
		return 3
	case ReasoningHigh:
		return 4
	case ReasoningXHigh:
		return 5
	case ReasoningMax:
		return 6
	default:
		return 0
	}
}
