func TestResolveEffortForLevels(t *testing.T) {
	tests := []struct {
		name          string
		value         string
		supported     []string
		wantEffort    string
		wantSource    string
		wantWarning   bool
		wantLogFields []string
	}{
		{
			name:        "named supported emits as caller",
			value:       "high",
			supported:   []string{"low", "medium", "high"},
			wantEffort:  "high",
			wantSource:  ResolutionSourceCaller,
			wantWarning: false,
		},
		{
			name:        "named unsupported snaps to nearest supported",
			value:       "high",
			supported:   []string{"low", "medium"},
			wantEffort:  "medium",
			wantSource:  ResolutionSourceSnapped,
			wantWarning: true,
			wantLogFields: []string{
				"requested=high",
				"resolved=medium",
				"supported=\"[low medium]\"",
				"discovery_source=test-cassette",
			},
		},
		{
			name:        "tokens convert to tier then validate",
			value:       "4096",
			supported:   []string{"low", "medium", "high"},
			wantEffort:  "medium",
			wantSource:  ResolutionSourceSnapped,
			wantWarning: false,
		},
		{
			name:        "empty discovery levels preserve existing numeric behavior",
			value:       "4096",
			supported:   nil,
			wantEffort:  "4096",
			wantSource:  ResolutionSourceCaller,
			wantWarning: false,
		},
		{
			name:        "unset is default",
			value:       "",
			supported:   []string{"low", "medium"},
			wantEffort:  "",
			wantSource:  ResolutionSourceDefault,
			wantWarning: false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var logBuf bytes.Buffer
			prev := slog.Default()
			slog.SetDefault(slog.New(slog.NewTextHandler(&logBuf, &slog.HandlerOptions{Level: slog.LevelWarn})))
			t.Cleanup(func() { slog.SetDefault(prev) })

			got := ResolveEffortForLevels(tt.value, tt.supported, EffortResolveOptions{
				Harness:         "codex",
				DiscoverySource: "test-cassette",
			})
			if got.Effort != tt.wantEffort || got.Source != tt.wantSource {
				t.Fatalf("ResolveEffortForLevels(%q, %v) = %#v, want effort=%q source=%q",
					tt.value, tt.supported, got, tt.wantEffort, tt.wantSource)
			}
			if (got.Warning != "") != tt.wantWarning {
				t.Fatalf("warning presence = %v, want %v (warning %q)", got.Warning != "", tt.wantWarning, got.Warning)
			}
			logText := logBuf.String()
			if tt.wantWarning && !strings.Contains(logText, "snapped to nearest supported tier") {
				t.Fatalf("structured warning log missing snap message: %s", logText)
			}
			if !tt.wantWarning && logText != "" {
				t.Fatalf("unexpected warning log: %s", logText)
			}
			for _, field := range tt.wantLogFields {
				if !strings.Contains(logText, field) {
					t.Fatalf("structured warning log missing %q: %s", field, logText)
				}
			}
		})
	}
}

